fn test_capsule_determinism_guarantees_low_rollback_risk() {
    let glass = GlassmorphismCapsule::new();

    // Run same operation 1000 times
    for _ in 0..1000 {
        glass.set_blur_level(50).unwrap();
        let css = glass.glass_purple_mid();
        assert!(css.contains("rgba"));  // Always same format
    }

    // If this passes, rollback won't be needed
